-- Hyprland 0.56+ native Lua configuration.
-- The previous autogenerated file is preserved in backups/2026-09-05-pre-setup/.

-- Reuse KDE's installed Miku XCursor theme. It has no Hyprcursor manifest, so
-- XCURSOR_THEME is the authoritative fallback for the compositor and apps.
hl.env("XCURSOR_THEME", "miku-cursor-linux")
hl.env("XCURSOR_SIZE", "48")
hl.env("HYPRCURSOR_SIZE", "48")

-- Grayscale AA avoids RGB/BGR color fringes and stays local to Hyprland.
hl.env("FONTCONFIG_FILE", "/home/hosh/.config/hypr/fontconfig-hyprland.conf")

-- Current Hyprland guidance for Electron/CEF; no legacy wlroots/NVIDIA globals.
hl.env("ELECTRON_OZONE_PLATFORM_HINT", "auto")

-- Session-local Qt6 palette/font integration. Plasma starts with its own
-- environment, so this does not replace KDE's appearance settings.
hl.env("QT_QPA_PLATFORMTHEME", "qt6ct")

require("monitors")
require("input")
require("appearance")
require("rules")
require("bindings")
require("autostart")
